const shifts=[];for(let y=8;y<im.height;y+=16)for(let x=8;x<im.width;x+=16){if(!A.inside({x,y},arena))continue;const k=(y*im.width+x)*4,bg=(this.low[k]+this.high[k])*.1495+(this.low[k+1]+this.high[k+1])*.2935+(this.low[k+2]+this.high[k+2])*.057;shifts.push(gray(im,x,y)-bg)}shifts.sort((a,b)=>a-b);this.offset=shifts.length?shifts[shifts.length>>1]:0;if(Math.abs(this.offset)>30){this.state='lighting';this.candidates=[];return[]}if(!scan)return[];
